parameters.jsCode:
// Code v2 — JavaScript — Run Once for All Items
const inputs = $input.all();

const classificationFields = [
  'original_language',
  'sentiment',
  'strength',
  'confidence',
];

const editorialFields = [
  'content_type',
  'topics',
  'relevance_score',
  'summary',
  'suggested_route',
  'needs_human_review',
  'assessment_note',
];

const languages = new Set(['pt', 'es', 'en', 'other']);

const sentiments = new Set([
  'Excited',
  'Happy',
  'Neutral',
  'Disappointed',
  'Angry',
]);

const contentTypes = new Set([
  'technical_answer',
  'job_achievement',
  'testimonial',
  'technical_question',
  'course_feedback',
  'debate',
  'noise',
]);

const routes = new Set([
  'success_case',
  'faq',
  'newsletter_only',
  'moderation',
  'discard',
]);

const outputFields = [
  'post_id',
  'source',
  'comments',
];

const commentOutputFields = [
  'comment_id',
  ...classificationFields,
  ...editorialFields,
];

function fail(message) {
  throw new Error(`Merge Classification: ${message}`);
}

function hasOwn(value, field) {
  return Object.prototype.hasOwnProperty.call(value, field);
}

function object(value, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    fail(`${label}: objeto inválido`);
  }

  return value;
}

function nonEmptyString(value, label) {
  if (typeof value !== 'string' || value.trim() === '') {
    fail(`${label}: string vazia ou inválida`);
  }

  return value;
}

function exactFields(value, expectedFields, label) {
  const allowed = new Set(expectedFields);

  const missing = expectedFields.filter(
    field => !hasOwn(value, field)
  );

  const extra = Object.keys(value).filter(
    field => !allowed.has(field)
  );

  if (missing.length || extra.length) {
    fail(
      `${label}: campos ausentes=[${missing.join(', ')}]; ` +
      `campos não permitidos=[${extra.join(', ')}]`
    );
  }
}

function idString(value, label) {
  if (typeof value !== 'string' || !/^[1-9][0-9]*$/.test(value)) {
    fail(label + ': ID deve ser string de inteiro positivo');
  }
  return value;
}

function rawId(value, label) {
  if (typeof value === 'number' && Number.isSafeInteger(value) && value > 0) {
    return String(value);
  }
  return idString(value, label);
}

function unitInterval(value, label) {
  if (
    typeof value !== 'number' ||
    !Number.isFinite(value) ||
    value < 0 ||
    value > 1
  ) {
    fail(`${label}: deve ser um número entre 0 e 1`);
  }
}

function validateTopics(value, label) {
  if (!Array.isArray(value) || value.length > 5) {
    fail(`${label}: deve ser um array com até cinco tópicos`);
  }

  const seen = new Set();

  value.forEach((topic, position) => {
    nonEmptyString(topic, `${label}[${position}]`);

    // Detecta repetições textuais, desconsiderando caixa e espaços.
    // Sinônimos ainda dependem da avaliação editorial.
    const key = topic
      .normalize('NFKC')
      .trim()
      .replace(/\s+/g, ' ')
      .toLocaleLowerCase('pt-BR');

    if (seen.has(key)) {
      fail(`${label}: tópico duplicado na posição ${position}`);
    }

    seen.add(key);
  });
}

function validateClassification(classification, id) {
  const label = `comentário ${id}`;

  exactFields(classification, commentOutputFields, label);

  idString(classification.comment_id, label + '.comment_id');

  if (!languages.has(classification.original_language)) {
    fail(`${label}: original_language inválido`);
  }

  if (!sentiments.has(classification.sentiment)) {
    fail(`${label}: sentiment inválido`);
  }

  unitInterval(classification.strength, `${label}.strength`);
  unitInterval(classification.confidence, `${label}.confidence`);

  if (!contentTypes.has(classification.content_type)) {
    fail(`${label}: content_type inválido`);
  }

  validateTopics(classification.topics, `${label}.topics`);

  if (
    !Number.isInteger(classification.relevance_score) ||
    classification.relevance_score < 0 ||
    classification.relevance_score > 100
  ) {
    fail(`${label}: relevance_score deve ser inteiro entre 0 e 100`);
  }

  nonEmptyString(classification.summary, `${label}.summary`);

  if (!routes.has(classification.suggested_route)) {
    fail(`${label}: suggested_route inválido`);
  }

  if (typeof classification.needs_human_review !== 'boolean') {
    fail(`${label}: needs_human_review deve ser boolean`);
  }

  nonEmptyString(
    classification.assessment_note,
    `${label}.assessment_note`
  );

  if (
    classification.content_type === 'noise' &&
    classification.suggested_route !== 'discard'
  ) {
    fail(`${label}: content_type noise exige suggested_route discard`);
  }

  if (
    classification.suggested_route === 'moderation' &&
    classification.needs_human_review !== true
  ) {
    fail(`${label}: rota moderation exige needs_human_review true`);
  }
}


return inputs.map((item, i) => {
  let original;
  let sent;
  try {
    original = $('Filter Comments').itemMatching(i).json;
    sent = $('Limit').itemMatching(i).json;
  } catch (error) {
    fail(`item ${i}: item linking indisponível ou ambíguo`);
  }

  object(original, 'original');
  object(sent, 'entrada do agente');
  object(sent.post, 'entrada.post');
  object(sent.comment, 'entrada.comment');

  const postId = idString(sent.post.id, 'entrada.post.id');
  const commentId = idString(sent.comment.id, 'entrada.comment.id');
  if (rawId(original.pub_story_id, 'original.pub_story_id') !== postId ||
      rawId(original.comment_id, 'original.comment_id') !== commentId) {
    fail(`item ${i}: IDs da entrada divergem do registro original`);
  }
  if (sent.post.source !== 'hackernews') {
    fail(`item ${i}: origem da entrada inválida`);
  }
  nonEmptyString(sent.source_file, 'entrada.source_file');
  nonEmptyString(sent.comment.text, 'entrada.comment.text');

  let result = item.json.output;
  if (typeof result === 'string') {
    try { result = JSON.parse(result); }
    catch (error) { fail(`item ${i}: output não contém JSON válido`); }
  }
  object(result, 'output');
  exactFields(result, outputFields, 'output');
  idString(result.post_id, 'output.post_id');
  if (result.post_id !== postId || result.source !== sent.post.source) {
    fail(`item ${i}: post_id ou source retornado diverge da entrada`);
  }
  if (!Array.isArray(result.comments) || result.comments.length !== 1) {
    fail(`item ${i}: output.comments deve conter exatamente um comentário`);
  }
  const classification = object(result.comments[0], 'output.comments[0]');
  validateClassification(classification, commentId);
  if (classification.comment_id !== commentId) {
    fail(`item ${i}: comment_id esperado=${commentId}; recebido=${classification.comment_id}`);
  }

  // Preserva post/comment e a proveniência da entrada, sem reconstrução pelo modelo.
  for (const field of [...classificationFields, ...editorialFields, 'editorial', 'routing']) {
    if (hasOwn(sent.comment, field)) {
      fail(`comentário ${commentId}: campo ${field} já existe na entrada`);
    }
  }
  for (const field of ['source', 'post_id', 'comment_id', 'suggested_route', 'needs_human_review', 'routing']) {
    if (hasOwn(sent, field)) {
      fail(`item ${i}: campo ${field} já existe na raiz da entrada`);
    }
  }

  const merged = JSON.parse(JSON.stringify(sent));
  for (const field of classificationFields) {
    merged.comment[field] = classification[field];
  }
  merged.comment.editorial = {};
  for (const field of editorialFields) {
    const value = classification[field];
    merged.comment.editorial[field] = Array.isArray(value) ? [...value] : value;
  }

  // Metadados para If/Switch; a execução da rota cabe aos nós seguintes.
  merged.source = sent.post.source;
  merged.post_id = postId;
  merged.comment_id = commentId;
  merged.suggested_route = classification.suggested_route;
  merged.needs_human_review = classification.needs_human_review;
  return { json: merged, pairedItem: { item: i } };
});
